cd /home/user/openai-nlogn-wiki/runs/P2 && cat > exegenius/tasks/0002-background.answer.json <<'EOF'
{
  "summary": "The reader is an undergraduate computer science student: they have taken programming, data structures, an algorithms course (asymptotic analysis, divide and conquer, sorting), discrete mathematics (sets, functions, induction, modular arithmetic, basic number theory) and an introductory linear algebra and complex numbers course, plus an introductory theory-of-computation course covering Turing machines. They have not met the Fourier transform beyond what the wiki explains, nor rings of polynomials modulo a polynomial, analytic number theory (prime density estimates), finite fields beyond bits, or any research-level complexity results on integer multiplication. Everything specific to the paper's fixed-tape constructions, networks, frames and numerical precision must be explained.",
  "known": [
    {
      "name": "Asymptotic notation Omega, Theta and little-o",
      "aliases": ["Ω", "Θ", "Big-Omega", "Big-Theta", "tight bound", "lower bound notation"],
      "gloss": "Ω(f) is an asymptotic lower bound, Θ(f) is both an upper and a lower bound of the same order, and o(f) is strictly smaller order, all as the input size grows."
    },
    {
      "name": "Logarithms, floors and ceilings",
      "aliases": ["log base 2", "lg", "natural logarithm", "floor function", "ceiling function", "⌈x⌉", "⌊x⌋"],
      "gloss": "The base-2 and natural logarithm with their usual laws, and the floor and ceiling functions rounding a real number down or up to an integer."
    },
    {
      "name": "Binary representation of integers",
      "aliases": ["binary numbers", "bit strings", "radix representation", "most significant bit", "least significant bit", "base-2 numerals", "n-bit integer"],
      "gloss": "A nonnegative integer is written as a string of bits whose value is the sum of bit times a power of 2, with the most significant bit leftmost, and the product of two n-bit numbers has at most 2n bits."
    },
    {
      "name": "Schoolbook binary addition with carries",
      "aliases": ["carry propagation", "ripple carry", "grade-school multiplication", "long addition", "long multiplication"],
      "gloss": "Adding or multiplying numbers digit by digit from the least significant end, passing a carry to the next position, which takes time linear in the length for addition and quadratic for the schoolbook product."
    },
    {
      "name": "Divide and conquer multiplication (Karatsuba, Toom-Cook)",
      "aliases": ["Karatsuba algorithm", "Toom-Cook", "Karatsuba-Ofman", "divide-and-conquer", "O(n^{log_2 3})"],
      "gloss": "Splitting each operand into halves or several pieces and recombining a smaller number of recursive products, giving subquadratic integer multiplication."
    },
    {
      "name": "Recurrences, induction and geometric sums",
      "aliases": ["recurrence relation", "proof by induction", "geometric series", "unrolling a recurrence", "master theorem"],
      "gloss": "Bounding a recursive cost by solving or unrolling a recurrence such as F_k ≤ cF_{k-1} + O(1), proved by induction and summed as a geometric series."
    },
    {
      "name": "Sets, functions, bijections and permutations",
      "aliases": ["Cartesian product", "bijection", "permutation", "involution", "function composition", "injective", "surjective", "index set", "indicator function"],
      "gloss": "Basic discrete mathematics: finite sets and their products, functions and their composition, bijections of a finite set onto itself (permutations), and involutions that are their own inverse."
    },
    {
      "name": "Binomial coefficients",
      "aliases": ["n choose k", "combinations", "C(n,k)", "counting subsets"],
      "gloss": "The number C(n,k) of k-element subsets of an n-element set, used to count the triples of an h-element set."
    },
    {
      "name": "Modular arithmetic and congruences",
      "aliases": ["integers mod n", "Z/nZ", "residues", "congruence", "a mod q", "cyclic group of integers mod n", "modular inverse"],
      "gloss": "Arithmetic on integers reduced modulo a positive integer q, with addition and multiplication of residues, so that addresses wrap around cyclically, and multiplication by a unit has an inverse."
    },
    {
      "name": "Greatest common divisor and the Euclidean algorithm",
      "aliases": ["gcd", "coprime", "relatively prime", "extended Euclidean algorithm", "Bezout identity", "modular inverse computation"],
      "gloss": "The largest common divisor of two integers, computed by the Euclidean algorithm, whose extended form finds the inverse of a number modulo another number coprime to it."
    },
    {
      "name": "Prime numbers",
      "aliases": ["primes", "prime factorization", "primality testing", "sieve of Eratosthenes", "distinct primes"],
      "gloss": "Integers greater than 1 with no divisors other than 1 and themselves, which can be found in a given range by scanning and testing or sieving."
    },
    {
      "name": "Chinese remainder theorem",
      "aliases": ["CRT", "Chinese remainder", "residues modulo coprime moduli"],
      "gloss": "For pairwise coprime moduli, an integer modulo their product is determined uniquely by its residues modulo each of them, and every combination of residues occurs."
    },
    {
      "name": "Roots of unity",
      "aliases": ["primitive root of unity", "nth roots of unity", "e^{2πi/n}", "unit-modulus roots", "twiddle factor"],
      "gloss": "The complex numbers ω with ω^n = 1, namely e^{2πik/n}, which are evenly spaced on the unit circle and satisfy Σ_k ω^{jk} = 0 for j not divisible by n."
    },
    {
      "name": "Matrices, matrix products and inverses",
      "aliases": ["matrix multiplication", "identity matrix", "invertible matrix", "diagonal matrix", "permutation matrix", "triangular matrix", "transpose", "linear map", "dot product", "inner product"],
      "gloss": "Linear maps written as arrays, composed by matrix product, with identity, inverse, diagonal, triangular and permutation matrices and the dot product of vectors."
    },
    {
      "name": "Gaussian elimination and row operations",
      "aliases": ["row reduction", "elementary row operations", "row addition", "row swap", "pivot"],
      "gloss": "Reducing a matrix to simpler form by adding a multiple of one row to another and swapping rows, which also shows that an invertible matrix is a product of elementary row operations."
    },
    {
      "name": "Vectors and matrices over the two-element field",
      "aliases": ["F_2", "GF(2)", "binary vectors", "linear algebra mod 2", "Hamming weight", "binary matrices", "GL(m, F_2)"],
      "gloss": "Linear algebra with bits as scalars under XOR and AND, where a vector is a bit string, its Hamming weight is the number of ones, and invertible binary matrices act on bit vectors."
    },
    {
      "name": "Vector norms and the triangle inequality",
      "aliases": ["max norm", "sup norm", "infinity norm", "absolute value bound", "error bound", "triangle inequality", "modulus bound"],
      "gloss": "A norm measures the size of a vector (here the largest modulus of its entries) and satisfies ‖u+v‖ ≤ ‖u‖ + ‖v‖, which is used to add up approximation errors."
    },
    {
      "name": "Two's complement and fixed-width signed integers",
      "aliases": ["signed binary", "twos complement", "signed words", "dyadic rationals", "binary fixed-point"],
      "gloss": "Representation of signed integers in a fixed number of bits, and of numbers with a power-of-two denominator as an integer times 2 to a negative power."
    },
    {
      "name": "Stacks and queues",
      "aliases": ["push and pop", "LIFO", "stack discipline", "last-in first-out", "queue"],
      "gloss": "Data structures in which items are added and removed at one end (stack, last in first out) or inserted at one end and removed at the other (queue), which a tape can simulate."
    },
    {
      "name": "Sorting and radix sort",
      "aliases": ["stable sort", "radix sorting", "merge sort", "sorting by keys", "binary radix sort", "merging sorted lists"],
      "gloss": "Rearranging records into order of their keys, with merging of sorted lists and stable radix sort that processes keys one bit or digit at a time."
    },
    {
      "name": "Binary counters and finite-state bookkeeping",
      "aliases": ["finite residue counter", "counting with a counter", "finite control counting", "ripple counting"],
      "gloss": "A counter stored in binary on a tape or in the finite control of a machine, incremented bit by bit with carries to keep track of a position or residue."
    }
  ]
}
EOF
cd /home/user/openai-nlogn-wiki/runs/P2 && exegenius submit 0002-background

